insert into public.products (id, category_id, name, slug, brand, description, condition, used_info, price, min_price, cost_price, stock, is_active, specs, created_at) values
  ('0db061bf-cc09-4122-99b7-588921e2e02d', 'db8a8681-1844-45ca-a3a9-4d5101d4cd70', 'Samsung Galaxy S24 8/256 ГБ', 'samsung-galaxy-s24-8-256', 'Samsung', 'Компактный флагман с ярким AMOLED-экраном 120 Гц, быстрым процессором и семью годами обновлений. Хорошо лежит в руке и отлично снимает днём и ночью.', 'new', null, 64990, 61990, 53300, 8, true, '{"screen":6.2,"memory":"256 ГБ","ram":"8 ГБ","camera":"50 + 12 + 10 Мп","battery":4000,"color":"Чёрный оникс","sim":"nano-SIM + eSIM","nfc":true}'::jsonb, '2026-11-17T12:40:15.252Z'),
  ('666d39f9-8fa2-4663-b429-012989a57089', 'db8a8681-1844-45ca-a3a9-4d5101d4cd70', 'Apple iPhone 15 128 ГБ', 'apple-iphone-15-128', 'Apple', 'Dynamic Island, основная камера 48 Мп и разъём USB-C. Алюминиевый корпус с матовым стеклом, которое не собирает отпечатки.', 'new', null, 69990, 67490, 57400, 6, true, '{"screen":6.1,"memory":"128 ГБ","ram":"6 ГБ","camera":"48 + 12 Мп","battery":3349,"color":"Голубой","sim":"nano-SIM + eSIM","nfc":true}'::jsonb, '2026-11-17T11:40:15.252Z'),
  ('77bc0d27-3342-4f66-baba-33b4d49fb26f', 'db8a8681-1844-45ca-a3a9-4d5101d4cd70', 'Xiaomi Redmi Note 13 Pro 8/256 ГБ', 'xiaomi-redmi-note-13-pro-8-256', 'Xiaomi', 'Камера 200 Мп, AMOLED-экран 120 Гц и быстрая зарядка 67 Вт в комплекте. Один из лучших вариантов в своей цене.', 'new', null, 24990, 23490, 20500, 14, true, '{"screen":6.67,"memory":"256 ГБ","ram":"8 ГБ","camera":"200 + 8 + 2 Мп","battery":5000,"color":"Полночный чёрный","sim":"2 nano-SIM","nfc":true}'::jsonb, '2026-11-17T10:40:15.252Z'),
  ('16f42120-8e4c-4806-9f7b-0c72e693247c', 'db8a8681-1844-45ca-a3a9-4d5101d4cd70', 'Samsung Galaxy A55 8/128 ГБ', 'samsung-galaxy-a55-8-128', 'Samsung', 'Металлическая рамка, защита от воды IP67 и экран Super AMOLED. Надёжный смартфон на каждый день с батареей на два дня.', 'new', null, 32990, null, 27100, 10, true, '{"screen":6.6,"memory":"128 ГБ","ram":"8 ГБ","camera":"50 + 12 + 5 Мп","battery":5000,"color":"Тёмно-синий","sim":"2 nano-SIM","nfc":true}'::jsonb, '2026-11-17T09:40:15.252Z'),
  ('6cf93a17-8d68-49d0-bfa9-2fd81fe1ed64', 'db8a8681-1844-45ca-a3a9-4d5101d4cd70', 'Apple iPhone 14 Pro 256 ГБ (Б/У)', 'apple-iphone-14-pro-256-bu', 'Apple', 'Проверенный Б/У смартфон в отличном состоянии: экран и корпус без царапин, все функции работают. Проверка при получении.', 'used', '{"grade":"excellent","batteryHealth":91,"warrantyMonths":3,"kit":"Коробка, кабель USB-C — Lightning"}'::jsonb, 62990, 59990, 44100, 1, true, '{"screen":6.1,"memory":"256 ГБ","ram":"6 ГБ","camera":"48 + 12 + 12 Мп","battery":3200,"color":"Космический чёрный","sim":"nano-SIM + eSIM","nfc":true}'::jsonb, '2026-11-17T08:40:15.252Z'),
  ('b453c70b-14d1-4128-b681-3608b6d1fb99', 'db8a8681-1844-45ca-a3a9-4d5101d4cd70', 'Apple iPhone 13 128 ГБ (Б/У)', 'apple-iphone-13-128-bu', 'Apple', 'Б/У смартфон в хорошем состоянии. Полностью исправен, Face ID и камеры работают. Небольшие следы использования на корпусе.', 'used', '{"grade":"good","batteryHealth":86,"warrantyMonths":1,"defects":"Мелкие царапины на рамке","kit":"Кабель, чехол в подарок"}'::jsonb, 34990, 32990, 24500, 1, true, '{"screen":6.1,"memory":"128 ГБ","ram":"4 ГБ","camera":"12 + 12 Мп","battery":3240,"color":"Тёмная ночь","sim":"nano-SIM + eSIM","nfc":true}'::jsonb, '2026-11-17T07:40:15.252Z'),
  ('207605b3-bbcd-479a-9c95-6a8b99b59d6a', 'db8a8681-1844-45ca-a3a9-4d5101d4cd70', 'Apple iPhone 12 64 ГБ (Б/У)', 'apple-iphone-12-64-bu', 'Apple', 'Недорогой Б/У iPhone для звонков, мессенджеров и соцсетей. Исправен, есть заметные следы использования — цена это учитывает.', 'used', '{"grade":"fair","batteryHealth":79,"warrantyMonths":1,"defects":"Царапины на экране, скол на углу корпуса","kit":"Только смартфон и кабель"}'::jsonb, 21990, 19990, 15400, 1, true, '{"screen":6.1,"memory":"64 ГБ","ram":"4 ГБ","camera":"12 + 12 Мп","battery":2815,"color":"Белый","sim":"nano-SIM + eSIM","nfc":true}'::jsonb, '2026-11-17T06:40:15.252Z'),
  ('668e73c0-d2d0-46f7-ad5e-1da024098cd1', 'db8a8681-1844-45ca-a3a9-4d5101d4cd70', 'Samsung Galaxy S22 8/128 ГБ (Б/У)', 'samsung-galaxy-s22-8-128-bu', 'Samsung', 'Компактный флагман прошлых лет в отличном состоянии. Экран без выгорания, корпус без сколов, аккумулятор держит день.', 'used', '{"grade":"excellent","warrantyMonths":3,"kit":"Коробка, кабель USB-C"}'::jsonb, 27990, null, 19600, 2, true, '{"screen":6.1,"memory":"128 ГБ","ram":"8 ГБ","camera":"50 + 12 + 10 Мп","battery":3700,"color":"Зелёный","sim":"2 nano-SIM","nfc":true}'::jsonb, '2026-11-17T05:40:15.252Z'),
  ('0d96c2df-a617-44a9-be9c-dea1651692ff', 'db8a8681-1844-45ca-a3a9-4d5101d4cd70', 'Xiaomi 12T 8/256 ГБ (Б/У)', 'xiaomi-12t-8-256-bu', 'Xiaomi', 'Б/У смартфон с камерой 108 Мп и зарядкой 120 Вт. Хорошее состояние, на экране наклеено защитное стекло.', 'used', '{"grade":"good","warrantyMonths":1,"defects":"Потёртости на задней крышке","kit":"Коробка, зарядное устройство 120 Вт, чехол"}'::jsonb, 17990, null, 12600, 1, true, '{"screen":6.67,"memory":"256 ГБ","ram":"8 ГБ","camera":"108 + 8 + 2 Мп","battery":5000,"color":"Серебристый","sim":"2 nano-SIM","nfc":true}'::jsonb, '2026-11-17T04:40:15.252Z'),
  ('d10e561b-34fe-4a2a-a9b7-c954b73abc9a', '5b88cf4d-230d-449f-9efd-e3cc3eb6f83d', 'Apple MacBook Air 13 M3 8/256 ГБ', 'apple-macbook-air-13-m3-8-256', 'Apple', 'Тонкий и бесшумный ноутбук без вентилятора. До 18 часов работы от батареи, экран Liquid Retina и чип M3 для работы и учёбы.', 'new', null, 104990, 99990, 86100, 2, true, '{"cpu":"Apple M3 (8 ядер)","ram":"8 ГБ","ssd":"256 ГБ","screen":13.6,"gpu":"Apple M3 GPU (8 ядер)","weight":1.24,"os":"macOS"}'::jsonb, '2026-11-17T03:40:15.252Z'),
  ('ca3901bb-0030-4e9a-9309-3b1b4287a581', '5b88cf4d-230d-449f-9efd-e3cc3eb6f83d', 'Lenovo IdeaPad Slim 5 14 16/512 ГБ', 'lenovo-ideapad-slim-5-14-16-512', 'Lenovo', 'Лёгкий металлический ноутбук с OLED-экраном и производительным Ryzen 7. Подсветка клавиатуры и быстрая зарядка через USB-C.', 'new', null, 62990, null, 51700, 5, true, '{"cpu":"AMD Ryzen 7 8845HS","ram":"16 ГБ","ssd":"512 ГБ","screen":14,"gpu":"AMD Radeon 780M","weight":1.46,"os":"Без ОС"}'::jsonb, '2026-11-17T02:40:15.252Z'),
  ('28fc6fca-74d6-4a7c-98ea-69f712bc52b7', '5b88cf4d-230d-449f-9efd-e3cc3eb6f83d', 'ASUS Vivobook 15 8/512 ГБ', 'asus-vivobook-15-8-512', 'ASUS', 'Доступный ноутбук для учёбы, офиса и фильмов. Большой экран 15,6 дюйма, цифровой блок клавиатуры и быстрый SSD.', 'new', null, 44990, null, 36900, 7, true, '{"cpu":"Intel Core i5-1335U","ram":"8 ГБ","ssd":"512 ГБ","screen":15.6,"gpu":"Intel Iris Xe","weight":1.7,"os":"Windows 11 Home"}'::jsonb, '2026-11-17T01:40:15.252Z'),
  ('aa0d5e79-4f2b-4dde-8453-6147379a0adc', '4cce0237-b86a-420d-9fa8-ad6c45d40127', 'Apple AirPods Pro 2 (USB-C)', 'apple-airpods-pro-2-usb-c', 'Apple', 'Активное шумоподавление, режим прозрачности и пространственный звук. Футляр с разъёмом USB-C и защитой от брызг.', 'new', null, 19990, null, 16400, 12, true, '{"type":"Внутриканальные","connection":"Bluetooth","anc":true,"battery_life":6,"color":"Белый"}'::jsonb, '2026-11-17T00:40:15.252Z'),
  ('489e2082-ef65-4456-a6c3-ab10aab4b01b', '4cce0237-b86a-420d-9fa8-ad6c45d40127', 'Sony WH-1000XM5', 'sony-wh-1000xm5', 'Sony', 'Полноразмерные наушники с одним из лучших шумоподавлений. Мягкие амбушюры, 30 часов работы и чистый звук в звонках.', 'new', null, 29990, 27990, 24600, 4, true, '{"type":"Полноразмерные","connection":"Bluetooth + кабель","anc":true,"battery_life":30,"color":"Чёрный"}'::jsonb, '2026-11-16T23:40:15.252Z'),
  ('2dbe1160-66ec-4eef-95b3-3e3319b6d735', '4cce0237-b86a-420d-9fa8-ad6c45d40127', 'Xiaomi Redmi Buds 5', 'xiaomi-redmi-buds-5', 'Xiaomi', 'Недорогие беспроводные наушники с шумоподавлением до 46 дБ. Лёгкие, с быстрой зарядкой: 5 минут — 2 часа музыки.', 'new', null, 2990, null, 2500, 25, true, '{"type":"Внутриканальные","connection":"Bluetooth","anc":true,"battery_life":10,"color":"Чёрный"}'::jsonb, '2026-11-16T22:40:15.252Z'),
  ('811b117d-8efc-4598-aa69-6a3d7c24d826', 'b7e1313c-8138-4d85-88cb-37d3a4539614', 'Apple Watch Series 10 46 мм', 'apple-watch-series-10-46', 'Apple', 'Самые тонкие Apple Watch с большим экраном. Отслеживание сна и тренировок, быстрая зарядка, ответы на звонки с запястья.', 'new', null, 39990, null, 32800, 5, true, '{"screen":1.96,"case_size":46,"battery_life":"До 18 часов","water":"50 м (WR50)","gps":true,"compat":"iOS","color":"Глянцевый чёрный"}'::jsonb, '2026-11-16T21:40:15.252Z'),
  ('85e742af-2019-4a9b-8f0f-a3100a91e58a', 'b7e1313c-8138-4d85-88cb-37d3a4539614', 'Samsung Galaxy Watch7 44 мм', 'samsung-galaxy-watch7-44', 'Samsung', 'Сапфировое стекло, точный двухдиапазонный GPS и анализ состава тела. Удобный ремешок и яркий экран под солнцем.', 'new', null, 22990, null, 18900, 6, true, '{"screen":1.5,"case_size":44,"battery_life":"До 40 часов","water":"5 АТМ, IP68","gps":true,"compat":"Android","color":"Зелёный"}'::jsonb, '2026-11-16T20:40:15.252Z'),
  ('4e4df6e6-11ab-453b-a7ec-04cbe23780e1', 'b7e1313c-8138-4d85-88cb-37d3a4539614', 'Xiaomi Smart Band 9', 'xiaomi-smart-band-9', 'Xiaomi', 'Фитнес-браслет с ярким AMOLED-экраном и батареей до трёх недель. Считает шаги, пульс, сон и 150 видов тренировок.', 'new', null, 3490, null, 2900, 30, true, '{"screen":1.62,"battery_life":"До 21 дня","water":"5 АТМ","gps":false,"compat":"iOS и Android","color":"Чёрный"}'::jsonb, '2026-11-16T19:40:15.252Z'),
  ('716d8e2f-91ea-4003-8584-0e9c22b416dd', 'e8574c59-1995-4061-882c-b7ab7a56f7a6', 'Dyson Supersonic HD15', 'dyson-supersonic-hd15', 'Dyson', 'Быстро сушит волосы без перегрева: датчик следит за температурой 40 раз в секунду. Пять магнитных насадок в комплекте.', 'new', null, 39990, 37990, 32800, 4, true, '{"power":1600,"modes":"3 скорости, 4 температуры","attachments":"Концентратор, диффузор, насадка для гладкости, для непослушных волос, расчёска","weight":650,"cord":2.7,"ionization":true,"color":"Никель / медь"}'::jsonb, '2026-11-16T18:40:15.252Z'),
  ('861101f0-a53a-4496-bcc6-beee2945e914', 'e8574c59-1995-4061-882c-b7ab7a56f7a6', 'Dyson Airwrap Complete Long', 'dyson-airwrap-complete-long', 'Dyson', 'Мультистайлер для длинных волос: сушит, завивает, выпрямляет и придаёт объём воздухом, без экстремальных температур.', 'new', null, 54990, null, 45100, 0, true, '{"power":1300,"modes":"3 скорости, 3 температуры","attachments":"Цилиндры 30 и 40 мм, щётки для гладкости, круглая щётка, фен-насадка","weight":680,"cord":2.6,"ionization":false,"color":"Синий / медный"}'::jsonb, '2026-11-16T17:40:15.252Z'),
  ('f75f4bed-695c-40ce-aed7-2b6d8881d837', 'e8574c59-1995-4061-882c-b7ab7a56f7a6', 'Xiaomi Mijia High Speed H500', 'xiaomi-mijia-high-speed-h500', 'Xiaomi', 'Компактный скоростной фен с ионизацией. Сушит волосы средней длины за пару минут и умещается в дорожную сумку.', 'new', null, 4990, null, 4100, 15, true, '{"power":1600,"modes":"2 скорости, 4 температуры","attachments":"Концентратор","weight":365,"cord":1.7,"ionization":true,"color":"Белый"}'::jsonb, '2026-11-16T16:40:15.252Z'),
  ('a0b2ff69-3a15-4761-a225-a9e72889bbd0', '9da0e869-8306-4570-bb81-35227f8dc6fe', 'Dyson V15 Detect Absolute', 'dyson-v15-detect-absolute', 'Dyson', 'Беспроводной пылесос с лазерной подсветкой пыли и счётчиком частиц на экране. До часа уборки на одном заряде.', 'new', null, 64990, 61990, 53300, 3, true, '{"type":"Вертикальный беспроводной","suction":"240 аВт","runtime":60,"dustbin":0.76,"weight":3.1,"wet":false}'::jsonb, '2026-11-16T15:40:15.252Z'),
  ('24b981c2-5aa6-40a1-8a87-dbc77ce2d9e6', '9da0e869-8306-4570-bb81-35227f8dc6fe', 'Xiaomi Robot Vacuum S20', 'xiaomi-robot-vacuum-s20', 'Xiaomi', 'Робот-пылесос с лазерной навигацией и влажной уборкой. Строит карту квартиры, объезжает препятствия, управляется со смартфона.', 'new', null, 17990, null, 14800, 6, true, '{"type":"Робот-пылесос","suction":"5000 Па","runtime":130,"dustbin":0.4,"weight":3.3,"wet":true}'::jsonb, '2026-11-16T14:40:15.252Z'),
  ('7b78516c-ab7b-4e59-85af-8c890ddd6e92', 'a925c70c-da6d-4250-bb83-7345ef969a3d', 'Зарядное устройство Anker Nano 20 Вт USB-C', 'anker-nano-20w-usb-c', 'Anker', 'Компактная быстрая зарядка для смартфонов и наушников. Не греется и не занимает соседнюю розетку.', 'new', null, 1290, null, 1100, 40, true, '{"type":"Зарядное устройство","compat":"iPhone, Android, наушники","power":20,"color":"Белый"}'::jsonb, '2026-11-16T13:40:15.252Z'),
